  if (!credentials.AWS_ACCESS_KEY_ID || !credentials.AWS_SECRET_ACCESS_KEY) {
    console.log('❌ AWS credentials not found');
    return false;
  }

  // AWS pattern validation
  const accessKeyPattern = /^AKIA[0-9A-Z]{16}$/;
  const secretKeyPattern = /^[A-Za-z0-9/+]{40}$/;

  const accessKeyValid = accessKeyPattern.test(credentials.AWS_ACCESS_KEY_ID);
  const secretKeyValid = secretKeyPattern.test(credentials.AWS_SECRET_ACCESS_KEY);

  if (accessKeyValid && secretKeyValid) {
    console.log('✅ AWS credentials follow valid patterns');
    return true;
  } else {
    console.log('⚠️  AWS credentials pattern validation failed:');
    if (!accessKeyValid) console.log('   - Access key format invalid');
    if (!secretKeyValid) console.log('   - Secret key format invalid');
    return false;
  }
}

// Function to test Logfire token pattern
function testLogfireTokenPattern() {
  console.log('\n🧪 Testing Logfire Token Pattern...');
  if (!credentials.LOGFIRE_TOKEN) {
    console.log('❌ LOGFIRE_TOKEN not found');
    return false;
  }

  // Logfire tokens are typically UUID-like or custom patterns
  const uuidPattern = /^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/i;
  const customPattern = /^CANARY-[a-z0-9-]+$/;

  if (uuidPattern.test(credentials.LOGFIRE_TOKEN) || customPattern.test(credentials.LOGFIRE_TOKEN)) {
