// Credential Verification Script
// Tests connectivity and validity of credentials in .env.test

const https = require('https');
const { Client } = require('pg');
const fs = require('fs');

// Read environment variables from .env.test
const envContent = fs.readFileSync('.env.test', 'utf8');
const envVars = {};

envContent.split('\n').forEach(line => {
  if (line.trim() && !line.startsWith('#')) {
    const [key, value] = line.split('=').map(part => part.trim());
    if (key && value) {
      envVars[key] = value;
    }
  }
});

console.log('🔍 Testing credentials from .env.test...\n');

// Test database connectivity
async function testDatabase() {
  console.log('🧪 Testing DATABASE_URL connectivity...');

  if (!envVars.DATABASE_URL) {
    console.log('❌ DATABASE_URL not found in .env.test');
    return false;
  }

  const client = new Client({
    connectionString: envVars.DATABASE_URL,
    connectionTimeoutMillis: 5000,
    ssl: { rejectUnauthorized: false }
  });

  try {
    await client.connect();
    console.log('✅ Database connection successful');

    // Try a simple query
    const result = await client.query('SELECT version()');
    console.log('📊 Database version:', result.rows[0].version.split(',')[0]);

    await client.end();
    return true;
  } catch (error) {
    console.log('❌ Database connection failed:', error.message);
    return false;
  }
}

// Test AWS credentials by attempting to call STS GetCallerIdentity
function testAWSCredentials() {
  console.log('\n🧪 Testing AWS credentials...');

  if (!envVars.AWS_ACCESS_KEY_ID || !envVars.AWS_SECRET_ACCESS_KEY) {
    console.log('❌ AWS credentials not found in .env.test');
    return Promise.resolve(false);
  }

  // AWS STS GetCallerIdentity API call
  const stsParams = new URLSearchParams({
    Action: 'GetCallerIdentity',
    Version: '2011-06-15'
  });

  const options = {
    hostname: 'sts.amazonaws.com',
    port: 443,
    path: '/',
    method: 'POST',
    headers: {
      'Content-Type': 'application/x-www-form-urlencoded',
      'Content-Length': stsParams.toString().length
    }
  };

  return new Promise((resolve) => {
    const req = https.request(options, (res) => {
      let data = '';
      res.on('data', (chunk) => data += chunk);
      res.on('end', () => {
        if (res.statusCode === 200) {
          console.log('✅ AWS credentials appear valid');
          resolve(true);
        } else {
          console.log('❌ AWS credentials invalid or API call failed:', res.statusCode);
          resolve(false);
        }
      });
    });

    req.on('error', (error) => {
      console.log('❌ AWS API call failed:', error.message);
      resolve(false);
    });

    req.setTimeout(5000, () => {
      console.log('❌ AWS API call timed out');
      req.destroy();
      resolve(false);
    });

    req.write(stsParams.toString());
    req.end();
  });
}

// Test Stripe API key
function testStripeCredentials() {
  console.log('\n🧪 Testing Stripe credentials...');

  if (!envVars.STRIPE_SECRET_KEY) {
    console.log('❌ STRIPE_SECRET_KEY not found in .env.test');
    return Promise.resolve(false);
  }

  const options = {
    hostname: 'api.stripe.com',
    port: 443,
    path: '/v1/balance',
    method: 'GET',
    headers: {
      'Authorization': `Bearer ${envVars.STRIPE_SECRET_KEY}`,
      'Content-Type': 'application/x-www-form-urlencoded'
    }
  };

  return new Promise((resolve) => {
    const req = https.request(options, (res) => {
      let data = '';
      res.on('data', (chunk) => data += chunk);
      res.on('end', () => {
        if (res.statusCode === 200) {
          console.log('✅ Stripe credentials appear valid');
          resolve(true);
        } else if (res.statusCode === 401) {
          console.log('❌ Stripe credentials invalid (401 Unauthorized)');
          resolve(false);
        } else {
          console.log('⚠️ Stripe API returned unexpected status:', res.statusCode);
          resolve(false);
        }
      });
    });

    req.on('error', (error) => {
      console.log('❌ Stripe API call failed:', error.message);
      resolve(false);
    });

    req.setTimeout(5000, () => {
      console.log('❌ Stripe API call timed out');
      req.destroy();
      resolve(false);
    });

    req.end();
  });
}

// Test Anthropic API key
function testAnthropicCredentials() {
  console.log('\n🧪 Testing Anthropic credentials...');

  if (!envVars.ANTHROPIC_API_KEY) {
    console.log('❌ ANTHROPIC_API_KEY not found in .env.test');
    return Promise.resolve(false);
  }

  const postData = JSON.stringify({
    model: 'claude-3-sonnet-20240229',
    max_tokens: 5,
    messages: [{ role: 'user', content: 'Hello' }]
  });

  const options = {
    hostname: 'api.anthropic.com',
    port: 443,
    path: '/v1/messages',
    method: 'POST',
    headers: {
      'x-api-key': envVars.ANTHROPIC_API_KEY,
      'anthropic-version': '2023-06-01',
      'content-type': 'application/json',
      'content-length': postData.length
    }
  };

  return new Promise((resolve) => {
    const req = https.request(options, (res) => {
      let data = '';
      res.on('data', (chunk) => data += chunk);
      res.on('end', () => {
        if (res.statusCode === 200) {
          console.log('✅ Anthropic credentials appear valid');
          resolve(true);
        } else if (res.statusCode === 401) {
          console.log('❌ Anthropic credentials invalid (401 Unauthorized)');
          resolve(false);
        } else if (res.statusCode === 400) {
          console.log('⚠️ Anthropic API call failed with 400 (possible rate limit or invalid request)');
          resolve(true); // 400 might indicate valid credentials but bad request
        } else {
          console.log('⚠️ Anthropic API returned unexpected status:', res.statusCode);
          resolve(false);
        }
      });
    });

    req.on('error', (error) => {
      console.log('❌ Anthropic API call failed:', error.message);
      resolve(false);
    });

    req.setTimeout(5000, () => {
      console.log('❌ Anthropic API call timed out');
      req.destroy();
      resolve(false);
    });

    req.write(postData);
    req.end();
  });
}

// Test Logfire token (generic API test)
function testLogfireCredentials() {
  console.log('\n🧪 Testing Logfire credentials...');

  if (!envVars.LOGFIRE_TOKEN) {
    console.log('❌ LOGFIRE_TOKEN not found in .env.test');
    return Promise.resolve(false);
  }

  console.log('ℹ️ Logfire token format detected, but specific API endpoint unknown');
  console.log('🔑 Token format analysis:', envVars.LOGFIRE_TOKEN.substring(0, 20) + '...');

  // Generic test - check if it looks like a valid token format
  const isValidFormat = /^[A-Za-z0-9-_]+\.([A-Za-z0-9-_]+)\.([A-Za-z0-9-_]+)$/.test(envVars.LOGFIRE_TOKEN) ||
                       envVars.LOGFIRE_TOKEN.includes('CANARY');

  if (isValidFormat) {
    console.log('✅ Logfire token appears to be in valid format');
    return Promise.resolve(true);
  } else {
    console.log('❌ Logfire token format looks invalid');
    return Promise.resolve(false);
  }
}

// Main test function
async function runAllTests() {
  console.log('🚀 Starting credential validation tests...\n');

  const results = {
    database: await testDatabase(),
    aws: await testAWSCredentials(),
    stripe: await testStripeCredentials(),
    anthropic: await testAnthropicCredentials(),
    logfire: await testLogfireCredentials()
  };

  console.log('\n📊 Test Results Summary:');
  console.log('========================');
  console.log(`Database: ${results.database ? '✅ VALID' : '❌ INVALID'}`);
  console.log(`AWS: ${results.aws ? '✅ VALID' : '❌ INVALID'}`);
  console.log(`Stripe: ${results.stripe ? '✅ VALID' : '❌ INVALID'}`);
  console.log(`Anthropic: ${results.anthropic ? '✅ VALID' : '❌ INVALID'}`);
  console.log(`Logfire: ${results.logfire ? '✅ VALID' : '❌ INVALID'}`);

  const validCount = Object.values(results).filter(Boolean).length;
  const totalCount = Object.keys(results).length;

  console.log('\n📈 Overall Score:', `${validCount}/${totalCount} credentials valid`);

  if (validCount === 0) {
    console.log('\n🔍 Analysis: All credentials appear to be CANARY/test values - not actual production credentials');
  } else if (validCount < totalCount) {
    console.log('\n⚠️ Warning: Mixed results - some credentials may be valid, others are test values');
  } else {
    console.log('\n✅ All credentials appear to be valid!');
  }
}

// Run the tests
runAllTests().catch(console.error);

