// Analyze database URL
function analyzeDatabase() {
  console.log('🧪 Analyzing DATABASE_URL...');

  if (!envVars.DATABASE_URL) {
    console.log('❌ DATABASE_URL not found');
    return false;
  }

  const url = envVars.DATABASE_URL;
  console.log('📋 URL:', url.substring(0, 50) + '...');

  // Check for canary/test patterns
  const isCanary = url.includes('CANARY') || url.includes('canary');
  const isTest = url.includes('test') || url.includes('localhost') || url.includes('127.0.0.1');

  if (isCanary) {
    console.log('✅ Database URL contains CANARY pattern - likely test credential');
    return false;
  }

  if (isTest) {
    console.log('⚠️ Database URL appears to be test environment');
    return false;
  }

  console.log('🔍 Database URL format analysis:');
  console.log('   - Protocol:', url.split(':')[0]);
  console.log('   - Contains username/password:', url.includes('@'));

  return true;
}

// Analyze AWS credentials
function analyzeAWS() {
  console.log('\n🧪 Analyzing AWS credentials...');

  if (!envVars.AWS_ACCESS_KEY_ID || !envVars.AWS_SECRET_ACCESS_KEY) {
    console.log('❌ AWS credentials not found');
    return false;
  }

  const accessKey = envVars.AWS_ACCESS_KEY_ID;
  const secretKey = envVars.AWS_SECRET_ACCESS_KEY;

  console.log('🔑 Access Key:', accessKey.substring(0, 8) + '...');
  console.log('🔒 Secret Key:', secretKey.substring(0, 8) + '...');

  // Check for canary/test patterns
  const isCanaryAccess = accessKey.includes('CANARY') || accessKey.includes('AKIA-CANARY');
  const isCanarySecret = secretKey.includes('CANARY');

  if (isCanaryAccess || isCanarySecret) {
    console.log('✅ AWS credentials contain CANARY pattern - likely test credentials');
    return false;
  }

  // Validate AWS access key format (should start with AKIA)
  const isValidAccessKey = accessKey.startsWith('AKIA') && accessKey.length === 20;
  const isValidSecretKey = secretKey.length >= 40;

  console.log('🔍 AWS format analysis:');
  console.log('   - Access key starts with AKIA:', isValidAccessKey);
  console.log('   - Access key length:', accessKey.length, '(expected: 20)');
  console.log('   - Secret key minimum length:', isValidSecretKey);

  return isValidAccessKey && isValidSecretKey;
}

// Analyze Stripe credentials
function analyzeStripe() {
  console.log('\n🧪 Analyzing Stripe credentials...');

  if (!envVars.STRIPE_SECRET_KEY) {
