    return false;
  }

  // Validate Stripe key format
  const isLiveKey = stripeKey.startsWith('sk-live-');
  const isTestKey = stripeKey.startsWith('sk-test-');
  const isValidFormat = stripeKey.startsWith('sk_') && stripeKey.length > 20;

  console.log('🔍 Stripe format analysis:');
  console.log('   - Starts with sk-live-:', isLiveKey);
  console.log('   - Starts with sk-test-:', isTestKey);
  console.log('   - Valid format:', isValidFormat);
  console.log('   - Key length:', stripeKey.length);

  if (isLiveKey && isValidFormat) {
    console.log('⚠️ WARNING: This appears to be a LIVE Stripe key');
    return true;
  }

  if (isTestKey) {
    console.log('✅ This is a test Stripe key');
    return false;
  }

  return isValidFormat;
}

// Analyze Anthropic credentials
function analyzeAnthropic() {
  console.log('\n🧪 Analyzing Anthropic credentials...');

  if (!envVars.ANTHROPIC_API_KEY) {
    console.log('❌ ANTHROPIC_API_KEY not found');
