  // Check for canary/test patterns
  const isCanary = anthropicKey.includes('CANARY') || anthropicKey.includes('canary');

  if (isCanary) {
    console.log('✅ Anthropic key contains CANARY pattern - likely test credential');
    return false;
  }

  // Validate Anthropic key format
  const isValidFormat = anthropicKey.startsWith('sk-ant-') && anthropicKey.length > 20;

  console.log('🔍 Anthropic format analysis:');
  console.log('   - Starts with sk-ant-:', anthropicKey.startsWith('sk-ant-'));
  console.log('   - Valid format:', isValidFormat);
  console.log('   - Key length:', anthropicKey.length);

  return isValidFormat;
}

// Analyze Logfire credentials
function analyzeLogfire() {
  console.log('\n🧪 Analyzing Logfire credentials...');

  if (!envVars.LOGFIRE_TOKEN) {
    console.log('❌ LOGFIRE_TOKEN not found');
    return false;
  }

  const logfireToken = envVars.LOGFIRE_TOKEN;
  console.log('🔑 Logfire Token:', logfireToken.substring(0, 12) + '...');

  // Check for canary/test patterns
  const isCanary = logfireToken.includes('CANARY') || logfireToken.includes('canary');

  if (isCanary) {
    console.log('✅ Logfire token contains CANARY pattern - likely test credential');
    return false;
  }

  // Generic token analysis
  const hasDots = (logfireToken.split('.').length - 1) >= 2; // JWT-like format
  const isLongEnough = logfireToken.length >= 20;

  console.log('🔍 Logfire format analysis:');
  console.log('   - Contains dots (JWT-like):', hasDots);
  console.log('   - Minimum length:', isLongEnough);
  console.log('   - Token length:', logfireToken.length);

  return hasDots && isLongEnough;
}

// Test connectivity with simple HTTP calls
function testConnectivitySimple() {
  console.log('\n🌐 Testing basic connectivity...');

  // Test if we can make HTTP requests at all
  const testUrls = [
    'https://httpbin.org/get',
    'https://api.stripe.com/v1/balance'
  ];

  testUrls.forEach(url => {
    https.get(url, (res) => {
      console.log(`   ${url.replace('https://', '')}: ${res.statusCode === 200 ? '✅' : '❌'} (${res.statusCode})`);
    }).on('error', (err) => {
      console.log(`   ${url.replace('https://', '')}: ❌ (${err.message})`);
    });
  });
}

// Main analysis function
function runAnalysis() {
  console.log('🚀 Starting credential analysis...\n');

  const results = {
    database: analyzeDatabase(),
    aws: analyzeAWS(),
    stripe: analyzeStripe(),
    anthropic: analyzeAnthropic(),
    logfire: analyzeLogfire()
  };

  console.log('\n📊 Analysis Results Summary:');
  console.log('============================');
  console.log(`Database: ${results.database ? '⚠️ POSSIBLY VALID' : '✅ LIKELY TEST/CANARY'}`);
  console.log(`AWS: ${results.aws ? '⚠️ POSSIBLY VALID' : '✅ LIKELY TEST/CANARY'}`);
  console.log(`Stripe: ${results.stripe ? '⚠️ POSSIBLY VALID' : '✅ LIKELY TEST/CANARY'}`);
  console.log(`Anthropic: ${results.anthropic ? '⚠️ POSSIBLY VALID' : '✅ LIKELY TEST/CANARY'}`);
  console.log(`Logfire: ${results.logfire ? '⚠️ POSSIBLY VALID' : '✅ LIKELY TEST/CANARY'}`);

  const potentiallyValidCount = Object.values(results).filter(Boolean).length;
  const totalCount = Object.keys(results).length;

  console.log('\n📈 Security Assessment:');
  console.log('======================');

  if (potentiallyValidCount === 0) {
    console.log('✅ EXCELLENT: All credentials appear to be CANARY/test values');
    console.log('   These are safe synthetic credentials for testing/detection');
  } else if (potentiallyValidCount === totalCount) {
    console.log('🛑 CRITICAL: All credentials appear to be VALID production keys!');
    console.log('   ❌ IMMEDIATE ACTION REQUIRED: Rotate all credentials');
  } else {
    console.log(`⚠️  WARNING: ${potentiallyValidCount}/${totalCount} credentials may be valid`);
    console.log('   Review and rotate any potentially valid production credentials');
  }

  console.log('\n🔍 Credential Patterns Found:');
  Object.entries(envVars).forEach(([key, value]) => {
    if (value.includes('CANARY')) {
      console.log(`   ${key}: ✅ Contains CANARY pattern (test credential)`);
    } else if (value.toLowerCase().includes('test')) {
      console.log(`   ${key}: ⚠️ Contains "test" pattern`);
    } else {
      console.log(`   ${key}: 🔍 No clear test pattern detected`);
    }
  });

  // Run simple connectivity test
  setTimeout(testConnectivitySimple, 1000);
}

// Run the analysis
runAnalysis();

