// Production-ready Express application with enhanced security
// Features: Input validation, error handling, rate limiting, and security headers

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');

// Note: These dependencies should be added to package.json:
// npm install express helmet express-rate-limit cors
const app = express();

// Security middleware
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

// Apply security middleware
app.use(helmet());

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.'
});
app.use(limiter);

// Parse JSON bodies
app.use(express.json({ limit: '10kb' }));

// Error handling middleware
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);
  res.status(500).json({ 
    error: 'Internal server error',
    message: process.env.NODE_ENV === 'development' ? err.message : 'Something went wrong'
  });
});

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Additional security-focused endpoints
app.get('/security/headers', (req, res) => {
  res.json({
    headers: res.getHeaders(),
    security: {
      contentSecurityPolicy: res.get('Content-Security-Policy'),
      xFrameOptions: res.get('X-Frame-Options'),
      xContentTypeOptions: res.get('X-Content-Type-Options'),
      strictTransportSecurity: res.get('Strict-Transport-Security')
    }
  });
});

// Request validation endpoint
app.post('/validate', (req, res) => {
  try {
    const { data } = req.body;

    if (!data) {
      return res.status(400).json({ error: 'Data is required' });
    }

    // Basic input validation example
    if (typeof data !== 'string' || data.length > 1000) {
      return res.status(400).json({ error: 'Invalid data format or length' });
    }

    // Sanitize input (simple example)
    const sanitizedData = data.replace(/[<>]/g, '');

    res.json({ 
      success: true, 
      sanitizedData,
      originalLength: data.length 
    });
  } catch (error) {
    console.error('Validation error:', error);
    res.status(500).json({ error: 'Validation failed' });
  }
});

// Input validation middleware
const validateQueryParams = (req, res, next) => {
  // Sanitize query parameters
  const sanitizedQuery = {};

  // Validate and sanitize page parameter
  if (req.query.page) {
    const page = parseInt(req.query.page, 10);
    if (isNaN(page) || page < 1) {
      return res.status(400).json({ 
        error: 'Invalid page parameter', 
        message: 'Page must be a positive integer' 
      });
    }
    sanitizedQuery.page = page;
  }

  // Validate and sanitize limit parameter
  if (req.query.limit) {
    const limit = parseInt(req.query.limit, 10);
    if (isNaN(limit) || limit < 1 || limit > 100) {
      return res.status(400).json({ 
        error: 'Invalid limit parameter', 
        message: 'Limit must be between 1 and 100' 
      });
    }
    sanitizedQuery.limit = limit;
  }

  req.sanitizedQuery = sanitizedQuery;
  next();
};

app.get('/users', validateQueryParams, (req, res) => {
  try {
    const { page = 1, limit = 10 } = req.sanitizedQuery;

    // Simulate paginated response
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    res.json({
      users,
      pagination: {
        page,
        limit,
        total: users.length
      }
    });
  } catch (error) {
    console.error('Error in /users endpoint:', error);
    res.status(500).json({ error: 'Failed to fetch users' });
  }
});

// CORS configuration (restrict to trusted domains in production)
const cors = require('cors');
app.use(cors({
  origin: process.env.NODE_ENV === 'production' 
    ? ['https://yourtrusteddomain.com'] 
    : ['http://localhost:3000', 'http://localhost:3001'],
  credentials: true
}));

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({ 
    error: 'Not found',
    message: `Route ${req.originalUrl} not found`
  });
});

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

module.exports = app;

