#!/usr/bin/env node

// Simple credential verification without external dependencies

const https = require('https');
const fs = require('fs');

// Simple function to parse .env files without dotenv
function parseEnvFile(filePath) {
    if (!fs.existsSync(filePath)) {
        console.log('❌ File not found:', filePath);
        return {};
    }

    const content = fs.readFileSync(filePath, 'utf8');
    const envVars = {};

    content.split('\n').forEach(line => {
        line = line.trim();
        if (line && !line.startsWith('#')) {
            const [key, ...valueParts] = line.split('=');
            if (key) {
                envVars[key.trim()] = valueParts.join('=').trim();
            }
        }
    });

    return envVars;
}

function testAWSValidity(awsAccessKey, awsSecretKey) {
    console.log('🔍 Testing AWS credentials...');

    if (!awsAccessKey || !awsSecretKey) {
        console.log('❌ AWS credentials not set');
        return false;
    }

    // AWS credentials pattern validation
    const accessKeyPattern = /^AKIA[0-9A-Z]{16}$/;
    const secretKeyPattern = /^[A-Za-z0-9+/]{40}$/;

    const accessKeyValid = accessKeyPattern.test(awsAccessKey);
    const secretKeyValid = secretKeyPattern.test(awsSecretKey);

    console.log(`AWS Access Key: ${awsAccessKey.substring(0, 8)}...`);
    console.log(`Format: ${accessKeyValid ? '✅ Valid' : '❌ Invalid'}`);
    console.log(`AWS Secret Key: ${awsSecretKey.substring(0, 8)}...`);
    console.log(`Format: ${secretKeyValid ? '✅ Valid' : '❌ Invalid'}`);

    return accessKeyValid && secretKeyValid;
}

function testStripeValidity(stripeKey) {
