    console.log(`Stripe Key: ${stripeKey.substring(0, 12)}...`);
    console.log(`Format: ${isValidFormat ? '✅ Valid' : '❌ Invalid'}`);

    return isValidFormat;
}

function testAnthropicValidity(anthropicKey) {
    console.log('\n🔍 Testing Anthropic credentials...');

    if (!anthropicKey) {
        console.log('❌ ANTHROPIC_API_KEY not set');
        return false;
    }

    // Anthropic key pattern validation
    const anthropicPattern = /^sk-ant-[a-zA-Z0-9_-]{40,}$/;
    const isValidFormat = anthropicPattern.test(anthropicKey);

    console.log(`Anthropic Key: ${anthropicKey.substring(0, 12)}...`);
    console.log(`Format: ${isValidFormat ? '✅ Valid' : '❌ Invalid'}`);

    return isValidFormat;
}

function testLogfireValidity(logfireToken) {
    console.log('\n🔍 Testing Logfire token...');

    if (!logfireToken) {
        console.log('❌ LOGFIRE_TOKEN not set');
        return false;
    }

    // Simple pattern check
    const logfirePattern = /^[a-zA-Z0-9_-]{20,}$/;
    const isValidFormat = logfirePattern.test(logfireToken);

    console.log(`Logfire Token: ${logfireToken.substring(0, 8)}...`);
    console.log(`Format: ${isValidFormat ? '✅ Valid' : '❌ Invalid'}`);

    return isValidFormat;
}

function testDatabaseConnection(dbUrl) {
    console.log('\n🔍 Testing database URL format...');

    if (!dbUrl) {
        console.log('❌ DATABASE_URL not set');
        return false;
    }

    // PostgreSQL URL pattern validation
    const dbPattern = /^postgres:\/\/[^:]+:[^@]+@[^:]+:\d+\/[^\s]+$/;
    const isValidFormat = dbPattern.test(dbUrl);

    console.log(`Database URL: ${dbUrl.split('@')[0]}@...`);
    console.log(`Format: ${isValidFormat ? '✅ Valid' : '❌ Invalid'}`);

    if (!isValidFormat) {
        return false;
    }

    // Try to extract components and validate structure
    try {
        const urlParts = dbUrl.match(/^postgres:\/\/([^:]+):([^@]+)@([^:]+):(\d+)\/(.+)$/);
        if (urlParts && urlParts.length === 6) {
            const [_, username, password, host, port, database] = urlParts;
