            console.log(`Host: ${host}`);
            console.log(`Port: ${port}`);
            console.log(`Database: ${database}`);
            console.log('✅ Database URL structure is valid');
            return true;
        }
    } catch (error) {
        console.log('❌ Database URL parsing failed');
    }

    return false;
}

async function main() {
