    console.log('\n📊 Summary of Results:');
    console.log('=====================');
    Object.entries(results).forEach(([service, valid]) => {
        console.log(`${service.toUpperCase()}: ${valid ? '✅ VALID FORMAT' : '❌ INVALID FORMAT'}`);
    });

    const allValidFormat = Object.values(results).every(result => result);

    if (allValidFormat) {
        console.log('\n✅ All credentials have valid format patterns.');
        console.log('💡 Note: This only checks format validity, not actual connectivity.');
    } else {
        console.log('\n⚠️  Some credentials have invalid format patterns.');
        console.log('💡 Recommendation: These credentials are likely stale or test values.');
    }

    // Check for "CANARY" patterns which indicate test/placeholder values
    console.log('\n🔍 Checking for test/canary patterns...');
    let hasCanaryValues = false;

    Object.entries(envVars).forEach(([key, value]) => {
        if (value.includes('CANARY')) {
            console.log(`⚠️  ${key} contains 'CANARY' - likely a test/placeholder value`);
            hasCanaryValues = true;
        }
    });

    if (hasCanaryValues) {
        console.log('\n🚨 WARNING: Credentials contain CANARY values.');
        console.log('These are likely placeholder/test values and should not be used in production.');
    }
}

