// Read and parse .env.test file
function parseEnvFile() {
  try {
    const content = fs.readFileSync('.env.test', 'utf8');
    const envVars = {};

    content.split('\n').forEach(line => {
      line = line.trim();
      if (line && !line.startsWith('#')) {
        const [key, ...valueParts] = line.split('=');
        if (key && valueParts.length > 0) {
          envVars[key.trim()] = valueParts.join('=').trim();
        }
      }
    });

    return envVars;
  } catch (error) {
    console.log('❌ Could not read .env.test file');
    return {};
  }
}

// Test HTTP connectivity to a URL
function testHttpRequest(url, options = {}) {
  return new Promise((resolve) => {
    const req = https.request(url, options, (res) => {
      let data = '';
      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        resolve({
          statusCode: res.statusCode,
          headers: res.headers,
          data: data
        });
      });
    });

    req.on('error', (error) => {
      resolve({
        error: error.message,
        statusCode: null
      });
    });

    req.setTimeout(5000, () => {
      req.destroy();
      resolve({
        error: 'Timeout',
        statusCode: null
      });
    });

    req.end();
  });
}

