      }
    });

    return envVars;
  } catch (error) {
    console.log('❌ Could not read .env.test file');
    process.exit(1);
  }
}

// Verify all credentials are canary values
function verifyCanaryCredentials(envVars) {
  console.log('🔍 Verifying credentials are canary values...');

  const credentialsToCheck = [
    'DATABASE_URL',
    'AWS_ACCESS_KEY_ID',
    'AWS_SECRET_ACCESS_KEY',
    'ANTHROPIC_API_KEY',
    'STRIPE_SECRET_KEY',
    'LOGFIRE_TOKEN'
  ];

  let allCanary = true;

  credentialsToCheck.forEach(key => {
    const value = envVars[key];
    if (value && !value.includes('CANARY')) {
      console.log(`❌ WARNING: ${key} does not contain CANARY pattern!`);
      console.log(`   Value: ${value.substring(0, 20)}...`);
      allCanary = false;
    }
