// Enhanced Express application with security best practices
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');
const app = express();

// Security middleware
app.use(helmet());
app.use(cors({
  origin: process.env.NODE_ENV === 'production' 
    ? ['https://yourdomain.com'] 
    : ['http://localhost:3000'],
  credentials: true
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Body parsing with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Input validation middleware
const validateInput = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Invalid input',
      details: errors.array()
    });
  }
  next();
};

// Security headers middleware
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
  next();
});

// Health endpoint with validation
app.get('/health', [
  // Add any query parameter validation if needed
], validateInput, (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      environment: process.env.NODE_ENV || 'development'
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ 
      error: 'Internal server error',
      message: process.env.NODE_ENV === 'production' 
        ? 'Internal server error' 
        : error.message
    });
  }
});

// Users endpoint with input validation
app.get('/users', [
  // Validate query parameters
  body('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
  body('offset').optional().isInt({ min: 0 }).withMessage('Offset must be a positive integer'),
], validateInput, async (req, res) => {
  try {
    const { limit = 10, offset = 0 } = req.query;

    // Input sanitization
    const sanitizedLimit = Math.min(parseInt(limit), 100);
    const sanitizedOffset = Math.max(parseInt(offset), 0);

    // Simulate database query with proper error handling
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    res.json({
      data: users,
      pagination: {
        limit: sanitizedLimit,
        offset: sanitizedOffset,
        total: users.length
      }
    });
  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({ 
      error: 'Failed to fetch users',
      message: process.env.NODE_ENV === 'production' 
        ? 'Internal server error' 
        : error.message
    });
  }
});

// 404 handler
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Endpoint not found',
    message: `Route ${req.originalUrl} does not exist`
  });
});

// Global error handler
app.use((error, req, res, next) => {
  console.error('Unhandled error:', error);

  if (error.type === 'entity.parse.failed') {
    return res.status(400).json({
      error: 'Invalid JSON format'
    });
  }

  res.status(500).json({
    error: 'Internal server error',
    message: process.env.NODE_ENV === 'production' 
      ? 'Internal server error' 
      : error.message
  });
});

// Graceful shutdown handling
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  process.exit(0);
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully');
  process.exit(0);
});

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

module.exports = app;

#!/usr/bin/env node

const { spawn } = require('child_process');
const https = require('https');
const { parse } = require('pg-connection-string');

// Read the .env.test file
const fs = require('fs');
const path = require('path');

console.log('🔍 Starting credential validation...\n');

// Parse .env.test file
const envPath = path.join(__dirname, '.env.test');
let envContent = '';

try {
  envContent = fs.readFileSync(envPath, 'utf8');
} catch (error) {
  console.error('❌ Could not read .env.test file:', error.message);
  process.exit(1);
}

// Parse environment variables
const envVars = {};
envContent.split('\n').forEach(line => {
  if (line.trim() && !line.startsWith('#')) {
    const [key, value] = line.split('=').map(item => item.trim());
    if (key && value) {
      envVars[key] = value;
    }
  }
});

console.log('📋 Found environment variables:');
Object.keys(envVars).forEach(key => {
  console.log(`   ${key}: ${envVars[key].substring(0, 20)}...`);
});
console.log('');

// Test functions
async function testPostgresConnection(dbUrl) {
  console.log('🐘 Testing PostgreSQL connection...');

  try {
    const parsed = parse(dbUrl);
    console.log(`   Host: ${parsed.host || 'localhost'}`);
    console.log(`   Port: ${parsed.port || 5432}`);
    console.log(`   Database: ${parsed.database}`);
    console.log(`   User: ${parsed.user}`);

    // Simple ping test using psql command
    const host = parsed.host || 'localhost';
    const port = parsed.port || 5432;

    return new Promise((resolve) => {
      const psql = spawn('psql', [
        '-h', host,
        '-p', port.toString(),
        '-U', parsed.user,
        '-d', parsed.database,
        '-c', 'SELECT 1 as test;',
        '-t'
      ]);

      let stdout = '';
      let stderr = '';

      psql.stdout.on('data', (data) => {
        stdout += data.toString();
      });

      psql.stderr.on('data', (data) => {
        stderr += data.toString();
      });

      psql.on('close', (code) => {
        if (code === 0 && stdout.includes('1')) {
          console.log('✅ PostgreSQL connection successful');
          resolve(true);
        } else {
          console.log('❌ PostgreSQL connection failed:', stderr.trim() || 'Connection refused');
          resolve(false);
        }
      });

      // Handle password if needed
      if (parsed.password) {
        psql.stdin.write(parsed.password + '\n');
        psql.stdin.end();
      }

      // Timeout after 10 seconds
      setTimeout(() => {
        psql.kill();
        console.log('❌ PostgreSQL connection timeout');
        resolve(false);
      }, 10000);
    });

  } catch (error) {
    console.log('❌ Invalid PostgreSQL URL format:', error.message);
    return false;
  }
}

function testAWSKeys(accessKeyId, secretAccessKey) {
  console.log('☁️  Testing AWS credentials format...');

  // Basic format validation
  const accessKeyPattern = /^AKIA[0-9A-Z]{16}$/;
  const secretKeyPattern = /^[A-Za-z0-9+/]{40}$/;

  const accessKeyValid = accessKeyPattern.test(accessKeyId);
  const secretKeyValid = secretKeyPattern.test(secretAccessKey);

  console.log(`   AWS Access Key ID format: ${accessKeyValid ? '✅ Valid' : '❌ Invalid'}`);
  console.log(`   AWS Secret Access Key format: ${secretKeyValid ? '✅ Valid' : '❌ Invalid'}`);

  return accessKeyValid && secretKeyValid;
}

function testAnthropicAPIKey(apiKey) {
  console.log('🤖 Testing Anthropic API key format...');

  // Anthropic API key format validation
  const anthropicPattern = /^sk-ant-[a-zA-Z0-9_-]{40,}$/;
  const isValid = anthropicPattern.test(apiKey);

  console.log(`   Anthropic API Key format: ${isValid ? '✅ Valid' : '❌ Invalid'}`);
  return isValid;
}

function testStripeSecretKey(secretKey) {
  console.log('💳 Testing Stripe secret key format...');

  // Stripe secret key format validation
  const stripePattern = /^(sk_(live|test)_[a-zA-Z0-9]{24,})$/;
  const isValid = stripePattern.test(secretKey);

  console.log(`   Stripe Secret Key format: ${isValid ? '✅ Valid' : '❌ Invalid'}`);

  if (isValid) {
    const isLive = secretKey.startsWith('sk-live-');
    console.log(`   Mode: ${isLive ? '🔴 LIVE (production)' : '🟢 TEST'}`);

    if (isLive) {
      console.log('   ⚠️  Warning: This appears to be a LIVE production key!');
    }
  }

  return isValid;
}

function testLogfireToken(token) {
  console.log('📊 Testing Logfire token format...');

  // Simple token format check (most tokens have some structure)
  const hasCanary = token.includes('CANARY');
  const isValidLength = token.length >= 20;

  console.log(`   Token contains 'CANARY': ${hasCanary ? '✅ Yes' : '❌ No'}`);
  console.log(`   Token length adequate: ${isValidLength ? '✅ Yes' : '❌ No'}`);

  if (hasCanary) {
    console.log('   ℹ️  This appears to be a synthetic/canary token');
  }

  return !hasCanary && isValidLength; // Consider valid if not a canary and has proper length
}

// Main validation function
async function validateCredentials() {
  const results = {
    postgres: false,
    aws: false,
    anthropic: false,
    stripe: false,
    logfire: false
  };

  // Test each credential
  if (envVars.DATABASE_URL) {
    results.postgres = await testPostgresConnection(envVars.DATABASE_URL);
  } else {
    console.log('❌ DATABASE_URL not found');
  }
  console.log('');

  if (envVars.AWS_ACCESS_KEY_ID && envVars.AWS_SECRET_ACCESS_KEY) {
    results.aws = testAWSKeys(envVars.AWS_ACCESS_KEY_ID, envVars.AWS_SECRET_ACCESS_KEY);
  } else {
    console.log('❌ AWS credentials not found');
  }
  console.log('');

  if (envVars.ANTHROPIC_API_KEY) {
    results.anthropic = testAnthropicAPIKey(envVars.ANTHROPIC_API_KEY);
  } else {
    console.log('❌ ANTHROPIC_API_KEY not found');
  }
  console.log('');

  if (envVars.STRIPE_SECRET_KEY) {
    results.stripe = testStripeSecretKey(envVars.STRIPE_SECRET_KEY);
  } else {
    console.log('❌ STRIPE_SECRET_KEY not found');
  }
  console.log('');

  if (envVars.LOGFIRE_TOKEN) {
    results.logfire = testLogfireToken(envVars.LOGFIRE_TOKEN);
  } else {
    console.log('❌ LOGFIRE_TOKEN not found');
  }
  console.log('');

  // Summary
  console.log('📊 VALIDATION SUMMARY:');
  console.log('======================');
  Object.entries(results).forEach(([service, valid]) => {
    const status = valid ? '✅ VALID' : '❌ INVALID';
    console.log(`${service.padEnd(12)}: ${status}`);
  });

  // Check for canary patterns
  const canaryDetected = Object.values(envVars).some(value => 
    value.includes('CANARY') || value.includes('canary')
  );

  if (canaryDetected) {
    console.log('\n⚠️  CANARY DETECTION:');
    console.log('===================');
    console.log('One or more credentials contain "CANARY" patterns.');
    console.log('These appear to be synthetic/test credentials for security monitoring.');
    console.log('They are likely intentionally invalid for production use.');
  }

  return results;
}

// Run validation
validateCredentials().catch(error => {
  console.error('❌ Validation failed:', error.message);
  process.exit(1);
});

