#!/usr/bin/env node

// Test script to verify connectivity and validity of credentials from .env.test

const { execSync } = require('child_process');
const readline = require('readline');

// Parse .env.test file
const fs = require('fs');

function parseEnvFile(filePath) {
  const content = fs.readFileSync(filePath, 'utf8');
  const envVars = {};

  content.split('\n').forEach(line => {
    line = line.trim();
    if (line && !line.startsWith('#')) {
      const [key, value] = line.split('=').map(part => part.trim());
      if (key && value) {
        envVars[key] = value;
      }
    }
  });

  return envVars;
}

async function testDatabaseConnection(dbUrl) {
  console.log('\n🔍 Testing Database Connection...');

  // Extract components from PostgreSQL URL
  const match = dbUrl.match(/^postgres:\/\/([^:]+):([^@]+)@([^:]+):(\d+)\/(.+)$/);
  if (!match) {
    console.log('❌ Invalid database URL format');
    return false;
  }

  const [, username, password, host, port, database] = match;

  console.log(`Host: ${host}:${port}`);
  console.log(`Database: ${database}`);
  console.log(`Username: ${username}`);

  // Test basic connectivity with telnet/ping
  try {
    // Test if host is reachable
    execSync(`ping -c 1 -W 2 ${host}`, { stdio: 'pipe' });
    console.log('✅ Host is reachable');
  } catch (error) {
    console.log('❌ Host is not reachable');
    return false;
  }

  // Test port connectivity
  try {
    execSync(`timeout 2 bash -c "echo > /dev/tcp/${host}/${port}"`, { stdio: 'pipe' });
    console.log('✅ Port is open');
    return true;
  } catch (error) {
    console.log('❌ Port is closed or unreachable');
    return false;
  }
}

async function testAWSKeys(accessKeyId, secretAccessKey) {
  console.log('\n🔍 Testing AWS Credentials...');

  // AWS credentials validation pattern
  const accessKeyPattern = /^AKIA[0-9A-Z]{16}$/;
  const secretKeyPattern = /^[A-Za-z0-9+/]{40}$/;

  if (accessKeyPattern.test(accessKeyId)) {
    console.log('✅ AWS Access Key ID format is valid');
  } else {
    console.log('❌ AWS Access Key ID format is invalid');
  }

  if (secretKeyPattern.test(secretAccessKey)) {
    console.log('✅ AWS Secret Access Key format is valid');
  } else {
    console.log('❌ AWS Secret Access Key format is invalid');
  }

  // Note: Actual AWS API calls would require proper AWS SDK and valid credentials
  console.log('⚠️  AWS credential validation requires AWS SDK for full verification');
  return true;
}

async function testStripeKey(apiKey) {
  console.log('\n🔍 Testing Stripe API Key...');

  const stripePattern = /^sk_(live|test)_[a-zA-Z0-9]{24}$/;

  if (stripePattern.test(apiKey)) {
    console.log('✅ Stripe API Key format is valid');

    // Try to make a basic API call to validate the key
    try {
      const result = execSync(`curl -s -u ${apiKey}: https://api.stripe.com/v1/balance \
        -H "Stripe-Version: 2023-10-16"`, { stdio: 'pipe', encoding: 'utf8' });

      if (result.includes('error')) {
        const error = JSON.parse(result);
        if (error.error && error.error.type === 'invalid_request_error') {
          console.log('✅ Stripe API Key is recognized (but invalid for this operation)');
        } else {
          console.log('❌ Stripe API Key validation failed:', error.error.message);
        }
      } else {
