let envContent;

try {
  envContent = fs.readFileSync(envPath, 'utf8');
} catch (error) {
  console.error('❌ Could not read .env.test file:', error.message);
  process.exit(1);
}

const envVars = {};
envContent.split('\n').forEach(line => {
  if (line.trim() && !line.startsWith('#')) {
    const [key, value] = line.split('=').map(part => part.trim());
    if (key && value) {
      envVars[key] = value;
    }
  }
});

console.log('📋 Found environment variables:');
Object.keys(envVars).forEach(key => {
  console.log(`  ${key}: ${envVars[key].slice(0, 20)}${envVars[key].length > 20 ? '...' : ''}`);
});
console.log('');

// Test Database URL
async function testDatabase() {
  const dbUrl = envVars.DATABASE_URL;
  if (!dbUrl) {
    console.log('❌ No DATABASE_URL found');
    return false;
  }

  console.log(`🧪 Testing Database: ${dbUrl.split('@')[1] || dbUrl}`);

  try {
    // Extract components from PostgreSQL URL
    const match = dbUrl.match(/postgres:\/\/([^:]+):([^@]+)@([^:]+):(\d+)\/(.+)/);
    if (!match) {
      console.log('❌ Invalid PostgreSQL URL format');
      return false;
    }

    const [_, username, password, host, port, database] = match;
    console.log(`   Host: ${host}, Port: ${port}, DB: ${database}`);

    // Simple TCP connection test (since we can't install PostgreSQL client here)
    const net = require('net');

    return new Promise((resolve) => {
      const socket = net.createConnection(port, host, () => {
        console.log('✅ Database host is reachable');
        socket.destroy();
        resolve(true);
      });

      socket.on('error', (error) => {
        console.log('❌ Database connection failed:', error.message);
        resolve(false);
      });

      socket.setTimeout(5000);
      socket.on('timeout', () => {
        console.log('❌ Database connection timeout');
        socket.destroy();
        resolve(false);
      });
    });

  } catch (error) {
    console.log('❌ Database test error:', error.message);
    return false;
  }
}

// Test AWS Credentials format
function testAWSCredentials() {
  const accessKey = envVars.AWS_ACCESS_KEY_ID;
  const secretKey = envVars.AWS_SECRET_ACCESS_KEY;

  console.log('🧪 Testing AWS Credentials format...');

  if (!accessKey || !secretKey) {
    console.log('❌ Missing AWS credentials');
    return false;
  }

  // Validate AWS Access Key format (should start with AKIA and be 20 characters)
  const accessKeyValid = /^AKIA[0-9A-Z]{16}$/.test(accessKey);
  const secretKeyValid = secretKey.length >= 40; // AWS secrets are typically 40 chars

  if (accessKeyValid && secretKeyValid) {
    console.log('✅ AWS credentials have valid format');
    return true;
  } else {
    console.log('❌ AWS credentials have invalid format');
    if (!accessKeyValid) console.log('   Access Key should start with AKIA and be 20 characters');
    if (!secretKeyValid) console.log('   Secret Key should be at least 40 characters');
    return false;
  }
}

// Test Anthropic API Key format
function testAnthropicKey() {
  const apiKey = envVars.ANTHROPIC_API_KEY;

