const validateQueryParams = (query, allowedParams) => {
  const invalidParams = Object.keys(query).filter(param => !allowedParams.includes(param));
  if (invalidParams.length > 0) {
    throw new Error(`Invalid query parameters: ${invalidParams.join(', ')}`);
  }
};

app.get('/users', (req, res, next) => {
  try {
    // Validate query parameters
    validateQueryParams(req.query, ['page', 'limit']);

    // Sanitize inputs
    const page = Math.max(1, parseInt(req.query.page) || 1);
    const limit = Math.min(50, Math.max(1, parseInt(req.query.limit) || 10));

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    res.json({
      data: users,
      pagination: { page, limit, total: users.length }
    });
  } catch (error) {
    next(error);
  }
});

