async function testPostgresConnection() {
  console.log('🧪 Testing PostgreSQL connection...');

  if (!credentials.DATABASE_URL) {
    console.log('❌ DATABASE_URL not found');
    return false;
  }

  try {
    const client = new Client({
      connectionString: credentials.DATABASE_URL,
      connectionTimeoutMillis: 5000,
      ssl: { rejectUnauthorized: false }
    });

    await client.connect();
    console.log('✅ PostgreSQL: Connection successful');
    await client.end();
    return true;
  } catch (error) {
    console.log(`❌ PostgreSQL: Connection failed - ${error.message}`);
    return false;
  }
}

// Test Stripe API key
function testStripeKey() {
  console.log('🧪 Testing Stripe API key...');

  if (!credentials.STRIPE_SECRET_KEY) {
    console.log('❌ STRIPE_SECRET_KEY not found');
    return false;
  }

  // Stripe keys follow specific patterns
  const stripePattern = /^sk_(live|test)_[a-zA-Z0-9]{24,}$/;
  const isValidFormat = stripePattern.test(credentials.STRIPE_SECRET_KEY);

  if (isValidFormat) {
    console.log('✅ Stripe: Key format appears valid');
  } else {
    console.log('❌ Stripe: Invalid key format');
  }

  return isValidFormat;
}

// Test AWS credentials format
function testAWSCredentials() {
  console.log('🧪 Testing AWS credentials format...');

  if (!credentials.AWS_ACCESS_KEY_ID || !credentials.AWS_SECRET_ACCESS_KEY) {
    console.log('❌ AWS credentials not found');
    return false;
  }

  // AWS Access Key ID pattern
  const accessKeyPattern = /^AKIA[0-9A-Z]{16}$/;
  const secretKeyPattern = /^[a-zA-Z0-9+/]{40}$/;

  const isAccessKeyValid = accessKeyPattern.test(credentials.AWS_ACCESS_KEY_ID);
  const isSecretKeyValid = credentials.AWS_SECRET_ACCESS_KEY.length >= 40;

  if (isAccessKeyValid) {
    console.log('✅ AWS Access Key: Format appears valid');
  } else {
    console.log('❌ AWS Access Key: Invalid format');
  }

  if (isSecretKeyValid) {
    console.log('✅ AWS Secret Key: Length appears valid');
  } else {
    console.log('❌ AWS Secret Key: Invalid length');
  }

  return isAccessKeyValid && isSecretKeyValid;
}

// Test Anthropic API key format
function testAnthropicKey() {
  console.log('🧪 Testing Anthropic API key format...');

  if (!credentials.ANTHROPIC_API_KEY) {
    console.log('❌ ANTHROPIC_API_KEY not found');
    return false;
  }

