  if (isValid) {
    console.log('✅ Anthropic: Key format appears valid');
  } else {
    console.log('❌ Anthropic: Invalid key format');
  }

  return isValid;
}

// Test Logfire token format
function testLogfireToken() {
  console.log('🧪 Testing Logfire token format...');

