#!/usr/bin/env node

const net = require('net');
const fs = require('fs');

// Parse the database URL from .env.test
function getDatabaseConfig() {
  try {
    const envContent = fs.readFileSync('.env.test', 'utf8');
    const dbLine = envContent.split('\n').find(line => line.startsWith('DATABASE_URL'));

    if (!dbLine) {
      console.log('❌ DATABASE_URL not found in .env.test');
      return null;
    }

    const dbUrl = dbLine.split('=')[1]?.trim();
    if (!dbUrl) {
      console.log('❌ Invalid DATABASE_URL format');
      return null;
    }

    // Parse PostgreSQL URL: postgres://user:password@host:port/database
    const match = dbUrl.match(/^postgres:\/\/([^:]+):([^@]+)@([^:]+):(\d+)\/(.+)$/);
    if (!match) {
      console.log('❌ Could not parse DATABASE_URL');
      return null;
    }

    return {
      user: match[1],
      password: match[2],
      host: match[3],
      port: parseInt(match[4]),
      database: match[5],
      url: dbUrl
    };
  } catch (error) {
    console.error('Error reading .env.test:', error.message);
    return null;
  }
}

// Test basic TCP connectivity to database host
