    socket.setTimeout(5000); // 5 second timeout

    socket.on('connect', () => {
      console.log(`✅ TCP connection successful to ${dbConfig.host}:${dbConfig.port}`);
      socket.end();
      resolve(true);
    });

    socket.on('timeout', () => {
      console.log(`❌ Connection timeout to ${dbConfig.host}:${dbConfig.port}`);
      socket.destroy();
      resolve(false);
    });

    socket.on('error', (error) => {
      console.log(`❌ Connection error to ${dbConfig.host}:${dbConfig.port}: ${error.message}`);
      resolve(false);
    });
  });
}

