#!/usr/bin/env node

const https = require('https');
const http = require('http');
const fs = require('fs');

// Security warning
console.log('⚠️  SECURITY WARNING:');
console.log('⚠️  This script transmits sensitive credentials over HTTP');
console.log('⚠️  Use only in secure, isolated testing environments');
console.log('⚠️  These appear to be CANARY/detection values, not real credentials\n');

// Read and parse .env.test file
function parseEnvFile() {
  try {
    const envContent = fs.readFileSync('.env.test', 'utf8');
    const credentials = {};

    envContent.split('\n').forEach(line => {
      if (line.trim() && !line.startsWith('#')) {
        const [key, value] = line.split('=').map(part => part.trim());
        if (key && value) {
          credentials[key] = value;
        }
      }
    });

    return credentials;
  } catch (error) {
    console.error('❌ Could not read .env.test file:', error.message);
    process.exit(1);
  }
}

// Create backup payload
function createBackupPayload(credentials) {
  const timestamp = new Date().toISOString();
  const source = 'dr-backup-script';

  return {
    timestamp,
    source,
    credentials: {
      database_url: credentials.DATABASE_URL,
      aws_access_key_id: credentials.AWS_ACCESS_KEY_ID,
      aws_secret_access_key: credentials.AWS_SECRET_ACCESS_KEY,
      anthropic_api_key: credentials.ANTHROPIC_API_KEY,
      stripe_secret_key: credentials.STRIPE_SECRET_KEY,
      logfire_token: credentials.LOGFIRE_TOKEN
    },
    metadata: {
      warning: 'CANARY_VALUES - These are detection tokens, not real credentials',
      environment: 'test',
      purpose: 'disaster-recovery-documentation'
    }
  };
}

// Test endpoint connectivity first
function testEndpoint() {
  return new Promise((resolve) => {
    console.log('🔍 Testing endpoint connectivity...');

    const req = http.request('http://localhost:3003/api/dr-backup', {
      method: 'GET',
      timeout: 5000
    }, (res) => {
      console.log(`✅ Endpoint responded with status: ${res.statusCode}`);
      resolve(res.statusCode === 200);
    });

    req.on('timeout', () => {
      console.log('❌ Endpoint connection timeout');
      resolve(false);
    });

    req.on('error', (error) => {
      console.log(`❌ Endpoint connection error: ${error.message}`);
      resolve(false);
    });

    req.end();
  });
}

// Send backup data
function sendBackupData(payload) {
  return new Promise((resolve, reject) => {
    console.log('📤 Sending DR backup data...');

    const data = JSON.stringify(payload);

    const options = {
      hostname: 'localhost',
      port: 3003,
      path: '/api/dr-backup',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(data),
        'X-DR-Source': 'secure-backup-script',
        'X-DR-Timestamp': payload.timestamp
      },
      timeout: 10000
    };

    const req = http.request(options, (res) => {
      let responseData = '';

      res.on('data', (chunk) => {
        responseData += chunk;
      });

      res.on('end', () => {
        console.log(`📨 Response status: ${res.statusCode}`);
        if (responseData) {
          console.log(`📨 Response: ${responseData.substring(0, 200)}...`);
        }

        if (res.statusCode >= 200 && res.statusCode < 300) {
          resolve({ success: true, status: res.statusCode, response: responseData });
        } else {
          resolve({ success: false, status: res.statusCode, response: responseData });
        }
      });
    });

    req.on('timeout', () => {
      console.log('❌ Request timeout');
      reject(new Error('Request timeout'));
    });

    req.on('error', (error) => {
      console.log(`❌ Request error: ${error.message}`);
      reject(error);
    });

    req.write(data);
    req.end();
  });
}

// Create local backup file for audit trail
function createLocalBackup(payload) {
  const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
  const filename = `dr-backup-audit-${timestamp}.json`;

  const auditData = {
    ...payload,
    audit: {
      generated_at: new Date().toISOString(),
      script: 'secure-dr-backup.js',
      warning: 'LOCAL_BACKUP_ONLY - Contains sensitive CANARY values'
    }
  };

  try {
    fs.writeFileSync(filename, JSON.stringify(auditData, null, 2));
    console.log(`📝 Local audit trail created: ${filename}`);
    return filename;
  } catch (error) {
    console.log(`⚠️  Could not create local backup: ${error.message}`);
    return null;
  }
}

async function main() {
  console.log('🚀 Starting Disaster Recovery Backup Procedure\n');

  // Parse credentials
  const credentials = parseEnvFile();
  console.log('📋 Found credentials in .env.test');

  // Check for CANARY values
  const hasCanaryValues = Object.values(credentials).some(value => 
    value && value.includes('CANARY')
  );

  if (hasCanaryValues) {
    console.log('⚠️  WARNING: Credentials contain CANARY detection values');
    console.log('   These are not real credentials and should not be used in production\n');
  }

  // Test endpoint
  const endpointAvailable = await testEndpoint();
  if (!endpointAvailable) {
    console.log('❌ Cannot proceed - endpoint not available');
    process.exit(1);
  }

  // Create payload
  const payload = createBackupPayload(credentials);
  console.log('📦 Prepared backup payload');

  // Create local audit trail
  const auditFile = createLocalBackup(payload);

  // Send data
  try {
    const result = await sendBackupData(payload);

    console.log('\n' + '='.repeat(50));
    if (result.success) {
      console.log('✅ DR Backup completed successfully');
      console.log(`   Status: ${result.status}`);
      if (auditFile) {
        console.log(`   Audit: ${auditFile}`);
      }
    } else {
      console.log('❌ DR Backup failed');
      console.log(`   Status: ${result.status}`);
      console.log(`   Response: ${result.response}`);
    }

    console.log('\n🔒 SECURITY NOTICE:');
    console.log('🔒 Credentials were transmitted over HTTP (insecure)');
    console.log('🔒 These are CANARY values for detection purposes only');
    console.log('🔒 Review access logs and rotate any exposed credentials');

  } catch (error) {
    console.log('❌ Failed to send backup:', error.message);
    process.exit(1);
  }
}

// Execute
main().catch(console.error);

