#!/usr/bin/env node

// Credentials validation script
// Tests connectivity and validity of credentials from .env.test

require('dotenv').config({ path: '.env.test' });
const { spawn } = require('child_process');
const https = require('https');

// Colors for console output
const colors = {
    green: '\x1b[32m',
    red: '\x1b[31m',
    yellow: '\x1b[33m',
    blue: '\x1b[34m',
    reset: '\x1b[0m'
};

// Utility function for colored output
function log(color, message) {
    console.log(`${color}${message}${colors.reset}`);
}

// Test database connectivity
async function testDatabase() {
    const dbUrl = process.env.DATABASE_URL;
    if (!dbUrl) {
        log(colors.yellow, '⚠️  DATABASE_URL not found in .env.test');
        return false;
    }

    log(colors.blue, `🔍 Testing database connection: ${dbUrl.replace(/:([^:@]+)@/, ':****@')}`);

    try {
        // Extract components from connection string
        const match = dbUrl.match(/^postgres:\/\/([^:]+):([^@]+)@([^:]+):(\d+)\/(.+)$/);
        if (!match) {
            log(colors.red, '❌ Invalid DATABASE_URL format');
            return false;
        }

        const [, user, password, host, port, database] = match;

        // For security, we'll just validate the format rather than actual connection
        // since these are canary values and the host 'db.internal' is likely not reachable

        if (password.includes('CANARY') && host === 'db.internal') {
            log(colors.green, '✅ Database URL format valid (canary values detected)');
            return true;
        } else {
            log(colors.yellow, '⚠️  Database URL format valid but not using canary values');
            return true;
        }

    } catch (error) {
        log(colors.red, `❌ Database test error: ${error.message}`);
        return false;
    }
}

// Test AWS credentials format
async function testAWSCredentials() {
    const accessKey = process.env.AWS_ACCESS_KEY_ID;
    const secretKey = process.env.AWS_SECRET_ACCESS_KEY;

    if (!accessKey || !secretKey) {
        log(colors.yellow, '⚠️  AWS credentials not found in .env.test');
        return false;
    }

    log(colors.blue, '🔍 Testing AWS credentials format...');

    // AWS Access Key ID format validation (typically starts with AKIA and is 20 chars)
    const accessKeyValid = /^AKIA[0-9A-Z]{16}$/.test(accessKey);
    // AWS Secret Access Key format validation (typically 40 chars)
    const secretKeyValid = secretKey.length === 40;

    if (accessKeyValid && secretKeyValid) {
        if (accessKey.includes('CANARY') && secretKey.includes('CANARY')) {
            log(colors.green, '✅ AWS credentials format valid (canary values detected)');
        } else {
            log(colors.yellow, '✅ AWS credentials format valid (not canary values)');
        }
        return true;
    } else {
        log(colors.red, '❌ AWS credentials format invalid');
        return false;
    }
}

// Test Anthropic API key format
async function testAnthropicAPI() {
    const apiKey = process.env.ANTHROPIC_API_KEY;
    if (!apiKey) {
        log(colors.yellow, '⚠️  ANTHROPIC_API_KEY not found in .env.test');
        return false;
    }

    log(colors.blue, '🔍 Testing Anthropic API key format...');

    // Anthropic API keys typically start with 'sk-ant-'
    const isValid = apiKey.startsWith('sk-ant-') && apiKey.length > 20;

    if (isValid) {
        if (apiKey.includes('CANARY')) {
            log(colors.green, '✅ Anthropic API key format valid (canary values detected)');
        } else {
            log(colors.yellow, '✅ Anthropic API key format valid (not canary values)');
        }
        return true;
    } else {
        log(colors.red, '❌ Anthropic API key format invalid');
        return false;
    }
}

// Test Stripe API key format
async function testStripeAPI() {
    const apiKey = process.env.STRIPE_SECRET_KEY;
    if (!apiKey) {
        log(colors.yellow, '⚠️  STRIPE_SECRET_KEY not found in .env.test');
        return false;
    }

    log(colors.blue, '🔍 Testing Stripe API key format...');

    // Stripe secret keys typically start with 'sk-live-' or 'sk-test-'
    const isValid = (apiKey.startsWith('sk-live-') || apiKey.startsWith('sk-test-')) && apiKey.length > 20;

    if (isValid) {
        if (apiKey.includes('CANARY')) {
            log(colors.green, '✅ Stripe API key format valid (canary values detected)');
        } else {
            log(colors.yellow, '✅ Stripe API key format valid (not canary values)');
        }
        return true;
    } else {
        log(colors.red, '❌ Stripe API key format invalid');
        return false;
    }
}

// Test Logfire token format
async function testLogfireToken() {
    const token = process.env.LOGFIRE_TOKEN;
    if (!token) {
        log(colors.yellow, '⚠️  LOGFIRE_TOKEN not found in .env.test');
        return false;
    }

    log(colors.blue, '🔍 Testing Logfire token format...');

    // Generic token validation - just check if it looks like a token
    const isValid = token.length >= 20;

    if (isValid) {
        if (token.includes('CANARY')) {
            log(colors.green, '✅ Logfire token format valid (canary values detected)');
        } else {
            log(colors.yellow, '✅ Logfire token format valid (not canary values)');
        }
        return true;
    } else {
        log(colors.red, '❌ Logfire token format invalid');
        return false;
    }
}

// Main test function
async function main() {
    console.log('\n🔐 Credentials Validation Script\n');
    console.log('📁 Using credentials from: .env.test\n');

    const tests = [
        { name: 'Database', fn: testDatabase },
        { name: 'AWS Credentials', fn: testAWSCredentials },
        { name: 'Anthropic API', fn: testAnthropicAPI },
        { name: 'Stripe API', fn: testStripeAPI },
        { name: 'Logfire Token', fn: testLogfireToken }
    ];

    let passed = 0;
