#!/usr/bin/env node

// Credential verification script
// Tests connectivity and validity of environment credentials

require('dotenv').config({ path: '.env.test' });

const https = require('https');
const { Client } = require('pg');

// Colors for console output
const colors = {
  reset: '\x1b[0m',
  red: '\x1b[31m',
  green: '\x1b[32m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m'
};

function logSuccess(message) {
  console.log(`${colors.green}✓${colors.reset} ${message}`);
}

function logWarning(message) {
  console.log(`${colors.yellow}⚠${colors.reset} ${message}`);
}

function logError(message) {
  console.log(`${colors.red}✗${colors.reset} ${message}`);
}

function logInfo(message) {
  console.log(`${colors.blue}ℹ${colors.reset} ${message}`);
}

async function testDatabaseConnection() {
  const dbUrl = process.env.DATABASE_URL;

  if (!dbUrl) {
    logError('DATABASE_URL not found in environment');
    return false;
  }

  logInfo(`Testing database connection: ${dbUrl.replace(/:([^:@]+)@/, ':***@')}`);

  try {
    // Parse the connection string
    const client = new Client({ 
      connectionString: dbUrl,
      connectionTimeoutMillis: 5000,
      ssl: { rejectUnauthorized: false }
    });

    await client.connect();
    const result = await client.query('SELECT version()');

    logSuccess('Database connection successful');
    logInfo(`PostgreSQL version: ${result.rows[0].version}`);

    await client.end();
    return true;
  } catch (error) {
    if (error.code === 'ENOTFOUND' || error.code === 'ECONNREFUSED') {
      logWarning(`Database host unreachable: ${error.message}`);
    } else if (error.code === '28P01') {
      logError('Database authentication failed - invalid credentials');
    } else {
      logError(`Database connection failed: ${error.message}`);
    }
    return false;
  }
}

async function testAWSCredentials() {
  const accessKey = process.env.AWS_ACCESS_KEY_ID;
  const secretKey = process.env.AWS_SECRET_ACCESS_KEY;

  if (!accessKey || !secretKey) {
    logError('AWS credentials not found in environment');
    return false;
  }

  logInfo('Testing AWS credentials format...');

  // Check if keys have the expected format
  const accessKeyValid = /^AKIA[0-9A-Z]{16}$/.test(accessKey);
  const secretKeyValid = /^[A-Za-z0-9+/]{40}$/.test(secretKey);

  if (accessKeyValid && secretKeyValid) {
    logSuccess('AWS credentials have valid format');

    // Note: We can't test actual AWS API calls without making real requests
    // which could incur costs or trigger security alerts
    logWarning('AWS credential validation requires actual API calls (skipped for safety)');
    return true;
  } else {
    logError('AWS credentials have invalid format');
    if (!accessKeyValid) logError(`Invalid access key format: ${accessKey}`);
    if (!secretKeyValid) logError(`Invalid secret key format: ${secretKey.substring(0, 8)}...`);
    return false;
  }
}

async function testStripeKey() {
  const stripeKey = process.env.STRIPE_SECRET_KEY;

  if (!stripeKey) {
    logError('STRIPE_SECRET_KEY not found in environment');
    return false;
  }

  logInfo('Testing Stripe key format...');

  // Stripe test keys start with sk-test-, live keys with sk-live-
  const isValidFormat = stripeKey.startsWith('sk-test-') || stripeKey.startsWith('sk-live-');

  if (isValidFormat) {
    logSuccess('Stripe key has valid format');

    // Test Stripe API connectivity (read-only endpoint)
    try {
      const response = await makeHttpsRequest({
        hostname: 'api.stripe.com',
        path: '/v1/balance',
        method: 'GET',
        auth: `${stripeKey}:`, // Stripe uses Basic auth with API key
        headers: {
          'Content-Type': 'application/x-www-form-urlencoded',
        }
      });

      if (response.statusCode === 200) {
        logSuccess('Stripe API connection successful');
        return true;
      } else if (response.statusCode === 401) {
        logError('Stripe authentication failed - invalid API key');
        return false;
      } else {
        logWarning(`Stripe API returned status: ${response.statusCode}`);
        return false;
      }
    } catch (error) {
      logWarning(`Stripe API test failed: ${error.message}`);
      return false;
    }
  } else {
    logError(`Invalid Stripe key format: ${stripeKey.substring(0, 10)}...`);
    return false;
  }
}

async function testAnthropicKey() {
  const anthropicKey = process.env.ANTHROPIC_API_KEY;

  if (!anthropicKey) {
    logError('ANTHROPIC_API_KEY not found in environment');
    return false;
  }

  logInfo('Testing Anthropic key format...');

  // Anthropic keys start with sk-ant-
  const isValidFormat = anthropicKey.startsWith('sk-ant-');

  if (isValidFormat) {
    logSuccess('Anthropic key has valid format');

    // Test Anthropic API connectivity
    try {
      const response = await makeHttpsRequest({
        hostname: 'api.anthropic.com',
        path: '/v1/messages',
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'x-api-key': anthropicKey,
          'anthropic-version': '2023-06-01'
        }
      }, JSON.stringify({
        model: 'claude-3-sonnet-20240229',
        max_tokens: 5,
        messages: [{ role: 'user', content: 'test' }]
      }));

      if (response.statusCode === 400) {
        // 400 Bad Request is expected for invalid messages - means authentication worked
        logSuccess('Anthropic API authentication successful');
        return true;
      } else if (response.statusCode === 401) {
        logError('Anthropic authentication failed - invalid API key');
        return false;
      } else {
        logWarning(`Anthropic API returned status: ${response.statusCode}`);
        return false;
      }
    } catch (error) {
      logWarning(`Anthropic API test failed: ${error.message}`);
      return false;
    }
  } else {
    logError(`Invalid Anthropic key format: ${anthropicKey.substring(0, 10)}...`);
    return false;
  }
}

async function testLogfireToken() {
  const logfireToken = process.env.LOGFIRE_TOKEN;

  if (!logfireToken) {
    logError('LOGFIRE_TOKEN not found in environment');
    return false;
  }

  logInfo('Testing Logfire token...');

  // Logfire tokens are typically UUID-like or base64
  const isValidFormat = /^[A-Za-z0-9-_]+$/.test(logfireToken) && logfireToken.length > 20;

  if (isValidFormat) {
    logSuccess('Logfire token has valid format');
    logWarning('Logfire token validation requires specific endpoint (validation skipped)');
    return true;
  } else {
    logError(`Invalid Logfire token format: ${logfireToken.substring(0, 10)}...`);
    return false;
  }
}

function makeHttpsRequest(options, postData = null) {
  return new Promise((resolve, reject) => {
    const req = https.request(options, (res) => {
      let data = '';
      res.on('data', (chunk) => data += chunk);
      res.on('end', () => resolve({
        statusCode: res.statusCode,
        headers: res.headers,
        data: data
      }));
    });

    req.on('error', reject);
    req.setTimeout(10000, () => {
      req.destroy();
      reject(new Error('Request timeout'));
    });

    if (postData) {
      req.write(postData);
    }

    req.end();
  });
}

async function main() {
