#!/usr/bin/env node

// Simple credential checker without external dependencies

const fs = require('fs');
const https = require('https');

// Read .env.test file directly
function readEnvFile() {
  try {
    const content = fs.readFileSync('.env.test', 'utf8');
    const envVars = {};

    content.split('\n').forEach(line => {
      line = line.trim();
      if (line && !line.startsWith('#')) {
        const [key, ...valueParts] = line.split('=');
        if (key && valueParts.length > 0) {
          envVars[key.trim()] = valueParts.join('=').trim();
        }
      }
    });

    return envVars;
  } catch (error) {
    console.error('❌ Could not read .env.test file:', error.message);
    process.exit(1);
  }
}

// Colors for console output
const colors = {
  reset: '\x1b[0m',
  red: '\x1b[31m',
  green: '\x1b[32m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m'
};

function log(message, color = null) {
  if (color) {
    console.log(color + message + colors.reset);
  } else {
    console.log(message);
  }
}

function analyzeCredentials(envVars) {
  console.log('🔍 Analyzing credentials from .env.test\n');

  const results = {};

  Object.entries(envVars).forEach(([key, value]) => {
    console.log(`${colors.blue}${key}${colors.reset}: ${maskSensitiveValue(value)}`);

    // Check for canary patterns
    const isCanary = value.includes('CANARY');
    const isValid = checkCredentialValidity(key, value);

    results[key] = { isCanary, isValid, value };

    if (isCanary) {
      console.log(`  ${colors.yellow}⚠️  CANARY VALUE - Likely synthetic${colors.reset}`);
    }

    console.log('');
  });

  return results;
}

function maskSensitiveValue(value) {
  if (value.length <= 8) return '***';
  return value.substring(0, 4) + '...' + value.substring(value.length - 4);
}

function checkCredentialValidity(key, value) {
  switch (key) {
    case 'DATABASE_URL':
      return isValidDatabaseUrl(value);
    case 'AWS_ACCESS_KEY_ID':
      return isValidAWSKey(value);
    case 'AWS_SECRET_ACCESS_KEY':
      return isValidAWSSecret(value);
    case 'ANTHROPIC_API_KEY':
      return isValidAnthropicKey(value);
    case 'STRIPE_SECRET_KEY':
      return isValidStripeKey(value);
    case 'LOGFIRE_TOKEN':
      return isValidLogfireToken(value);
    default:
      return true; // Unknown key type
  }
}

function isValidDatabaseUrl(url) {
  // Basic PostgreSQL URL validation
  return url.startsWith('postgres://') || url.startsWith('postgresql://');
}

function isValidAWSKey(key) {
  // AWS access key pattern: AKIA followed by 16 uppercase alphanumeric chars
  return /^AKIA[0-9A-Z]{16}$/.test(key);
}

function isValidAWSSecret(secret) {
  // AWS secret key pattern: 40-character base64-like string
  return /^[A-Za-z0-9+/]{40}$/.test(secret);
}

function isValidAnthropicKey(key) {
  // Anthropic keys start with sk-ant-
  return key.startsWith('sk-ant-');
}

function isValidStripeKey(key) {
  // Stripe keys start with sk-test- or sk-live-
  return key.startsWith('sk-test-') || key.startsWith('sk-live-');
}

function isValidLogfireToken(token) {
  // Generic token validation
  return token.length >= 20 && /^[A-Za-z0-9-_]+$/.test(token);
}

async function testConnectivity() {
  console.log('🌐 Testing external connectivity...\n');

  // Test basic internet connectivity
  try {
    await testHttpsRequest('https://www.google.com', 'GET');
    log('✅ Internet connectivity: OK', colors.green);
  } catch (error) {
    log('❌ Internet connectivity: FAILED', colors.red);
    log(`   Error: ${error.message}`, colors.red);
  }

  console.log('');
}

function testHttpsRequest(url, method = 'GET') {
  return new Promise((resolve, reject) => {
    const { hostname, pathname } = new URL(url);

    const options = {
      hostname,
      path: pathname,
      method,
      timeout: 10000
    };

    const req = https.request(options, (res) => {
      if (res.statusCode >= 200 && res.statusCode < 400) {
        resolve();
      } else {
        reject(new Error(`HTTP ${res.statusCode}`));
      }
    });

    req.on('error', reject);
    req.on('timeout', () => {
      req.destroy();
      reject(new Error('Timeout'));
    });

    req.end();
  });
}

function generateSummary(results) {
  console.log('='.repeat(60));
  console.log('📊 CREDENTIAL ANALYSIS SUMMARY');
  console.log('='.repeat(60));

  let canaryCount = 0;
  let invalidCount = 0;

  Object.entries(results).forEach(([key, { isCanary, isValid }]) => {
    const status = isCanary ? 
      `${colors.yellow}CANARY${colors.reset}` : 
      (isValid ? `${colors.green}VALID${colors.reset}` : `${colors.red}INVALID${colors.reset}`);

    console.log(`${key.padEnd(25)}: ${status}`);

    if (isCanary) canaryCount++;
    if (!isValid) invalidCount++;
  });

  console.log('');
  console.log(`${colors.blue}Total credentials:${colors.reset} ${Object.keys(results).length}`);
  console.log(`${colors.yellow}Canary values:${colors.reset} ${canaryCount}`);
  console.log(`${colors.red}Invalid formats:${colors.reset} ${invalidCount}`);

  if (canaryCount > 0) {
    console.log('\n' + '⚠️  ' + colors.yellow + 'CANARY VALUES DETECTED' + colors.reset);
    console.log(colors.yellow + 'These credentials appear to be synthetic values for security monitoring.');
    console.log('They are likely not intended for actual use and may trigger security alerts if used.' + colors.reset);
  }

  if (invalidCount > 0) {
    console.log('\n' + '❌ ' + colors.red + 'INVALID FORMATS DETECTED' + colors.reset);
    console.log(colors.red + 'Some credentials do not match expected patterns for their service types.' + colors.reset);
  }
}

async function main() {
  const envVars = readEnvFile();

  await testConnectivity();

  const results = analyzeCredentials(envVars);
  generateSummary(results);

  console.log('\n' + '='.repeat(60));
  console.log('💡 RECOMMENDATIONS:');
  console.log('='.repeat(60));

  if (Object.values(results).some(r => r.isCanary)) {
    console.log('1. Replace canary values with actual production credentials');
    console.log('2. Ensure these are test values only, not used in production');
    console.log('3. Consider rotating credentials if they have been compromised');
  } else {
    console.log('1. Credentials appear to be valid format');
    console.log('2. Test actual API connectivity for each service');
    console.log('3. Consider regular credential rotation');
  }
}

main().catch(console.error);

