// Test database connectivity
function testDatabaseConnectivity(host, port) {
    return new Promise((resolve) => {
        const socket = net.createConnection({ host, port, timeout: 5000 });

        socket.on('connect', () => {
            console.log(`✅ Database: Connected to ${host}:${port}`);
            socket.end();
            resolve(true);
        });

        socket.on('timeout', () => {
            console.log(`❌ Database: Timeout connecting to ${host}:${port}`);
            socket.destroy();
            resolve(false);
        });

        socket.on('error', (error) => {
            console.log(`❌ Database: Cannot connect to ${host}:${port} - ${error.code}`);
            resolve(false);
        });
    });
}

// Test HTTP endpoint connectivity
function testHttpConnectivity(url) {
    return new Promise((resolve) => {
        try {
            const req = https.get(url, { timeout: 5000 }, (res) => {
                console.log(`✅ ${url}: HTTP ${res.statusCode}`);
                resolve(true);
            });

            req.on('timeout', () => {
                console.log(`❌ ${url}: Timeout`);
                req.destroy();
                resolve(false);
            });

            req.on('error', (error) => {
                console.log(`❌ ${url}: Error - ${error.code}`);
                resolve(false);
            });
        } catch (error) {
            console.log(`❌ ${url}: Invalid URL or configuration`);
            resolve(false);
        }
    });
}

