#!/usr/bin/env node

/**
 * Secure Credential Backup Utility
 * Safely backs up credentials for disaster recovery
 */

const fs = require('fs');
const crypto = require('crypto');

// Parse environment file
function parseEnvFile(filePath) {
  try {
    const content = fs.readFileSync(filePath, 'utf8');
    const envVars = {};

    content.split('\n').forEach(line => {
      line = line.trim();
      if (!line || line.startsWith('#')) return;

      const match = line.match(/^([^=]+)=(.+)$/);
      if (match) {
        envVars[match[1].trim()] = match[2].trim();
      }
    });

    return envVars;
  } catch (error) {
    console.error(`Error reading ${filePath}: ${error.message}`);
    return {};
  }
}

// Encrypt data with a passphrase
function encryptData(data, passphrase) {
  const algorithm = 'aes-256-gcm';
  const iv = crypto.randomBytes(16);
  const key = crypto.createHash('sha256').update(passphrase).digest();

  const cipher = crypto.createCipheriv(algorithm, key, iv);
  let encrypted = cipher.update(JSON.stringify(data), 'utf8', 'hex');
  encrypted += cipher.final('hex');

  const authTag = cipher.getAuthTag();

  return {
    iv: iv.toString('hex'),
    authTag: authTag.toString('hex'),
    encryptedData: encrypted
  };
}

// Generate secure backup
function generateSecureBackup() {
  const envVars = parseEnvFile('.env.test');

  if (Object.keys(envVars).length === 0) {
    console.error('No credentials found to backup');
    process.exit(1);
  }

  // Filter only credentials (not general config)
  const credentials = {};
  const credentialPatterns = [
    /_URL$/,
    /_KEY$/,
    /_SECRET$/,
    /_TOKEN$/,
    /_PASSWORD$/,
    /_ACCESS_/
  ];

  Object.entries(envVars).forEach(([key, value]) => {
    if (credentialPatterns.some(pattern => pattern.test(key))) {
      credentials[key] = value;
    }
  });

  // Generate encryption passphrase (should be provided by user)
  const passphrase = process.argv[2] || crypto.randomBytes(32).toString('hex');

  if (!process.argv[2]) {
    console.warn('⚠️  Using auto-generated passphrase. Provide a secure passphrase as argument for production use.');
    console.warn(`Generated passphrase: ${passphrase}`);
    console.warn('SAVE THIS PASSPHRASE SECURELY - IT WILL BE REQUIRED FOR DECRYPTION');
  }

  // Encrypt credentials
  const encrypted = encryptData(credentials, passphrase);

  // Create backup file
  const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
  const backupFilename = `credentials-backup-${timestamp}.encrypted`;

  const backupData = {
    version: '1.0',
    timestamp: new Date().toISOString(),
    credentialsCount: Object.keys(credentials).length,
    encrypted: encrypted
  };

  fs.writeFileSync(backupFilename, JSON.stringify(backupData, null, 2));

  console.log(`✅ Secure backup created: ${backupFilename}`);
  console.log(`📊 Backed up ${Object.keys(credentials).length} credentials`);
  console.log('🔒 Credentials are encrypted with AES-256-GCM');

  if (!process.argv[2]) {
    console.log('\n🔑 PASSPHRASE FOR DECRYPTION:');
    console.log(passphrase);
    console.log('\n⚠️  Store this passphrase securely in your password manager!');
  }

  return backupFilename;
}

// Emergency access instructions
function generateEmergencyInstructions() {
  const instructions = `
🚨 EMERGENCY CREDENTIAL ACCESS PROCEDURE
=========================================

THIS IS FOR DISASTER RECOVERY ONLY

1. LOCATE ENCRYPTED BACKUP FILE
