⏰ RESPONSE TIMEFRAME: < 15 minutes for critical services
`;

  fs.writeFileSync('EMERGENCY_ACCESS_INSTRUCTIONS.md', instructions);
  console.log('📋 Emergency access instructions created: EMERGENCY_ACCESS_INSTRUCTIONS.md');
}

// Main execution
if (require.main === module) {
  console.log('🔐 Secure Credential Backup Utility\n');

  if (process.argv[2] === '--help') {
    console.log('Usage: node secure-backup.js [passphrase]');
    console.log('  passphrase: Optional encryption passphrase (recommended for production)');
    console.log('              If omitted, a random passphrase will be generated and displayed');
    process.exit(0);
  }

  try {
    generateSecureBackup();
