#!/usr/bin/env node

/**
 * Secure Credential Decryption Utility
 * Decrypts backup files for emergency access
 */

const fs = require('fs');
const crypto = require('crypto');

// Decrypt data with passphrase
function decryptData(encryptedData, iv, authTag, passphrase) {
  const algorithm = 'aes-256-gcm';
  const key = crypto.createHash('sha256').update(passphrase).digest();

  const decipher = crypto.createDecipheriv(algorithm, key, Buffer.from(iv, 'hex'));
  decipher.setAuthTag(Buffer.from(authTag, 'hex'));

  let decrypted = decipher.update(encryptedData, 'hex', 'utf8');
  decrypted += decipher.final('utf8');

  return JSON.parse(decrypted);
}

// Main decryption function
function decryptBackup(backupFile, passphrase) {
  try {
    const backupData = JSON.parse(fs.readFileSync(backupFile, 'utf8'));

    if (backupData.version !== '1.0') {
      throw new Error('Unsupported backup version');
    }

    const { iv, authTag, encryptedData } = backupData.encrypted;

    console.log(`🔓 Decrypting backup from ${backupData.timestamp}`);
    console.log(`📊 Contains ${backupData.credentialsCount} credentials\n`);

    const credentials = decryptData(encryptedData, iv, authTag, passphrase);

    // Create decrypted output
    const outputFile = backupFile.replace('.encrypted', '.decrypted.json');
    fs.writeFileSync(outputFile, JSON.stringify(credentials, null, 2));

    console.log(`✅ Successfully decrypted: ${outputFile}`);
    console.log('\n📋 Credentials available:');
    Object.keys(credentials).forEach(key => {
      console.log(`   - ${key}`);
    });

    console.log('\n🚨 SECURITY WARNING:');
    console.log('   - This file contains sensitive credentials');
    console.log('   - Use only for emergency recovery');
    console.log('   - Delete this file immediately after use');
    console.log('   - Rotate all credentials after emergency access');

    return outputFile;

  } catch (error) {
    if (error.message.includes('bad auth tag')) {
      throw new Error('Invalid passphrase - decryption failed');
    }
    throw error;
  }
}

// Emergency access logging
function logEmergencyAccess() {
  const logEntry = {
    timestamp: new Date().toISOString(),
    user: process.env.USER || 'unknown',
    host: require('os').hostname(),
    action: 'emergency_decryption',
    success: true
  };

  const logFile = 'emergency-access.log';
  const logData = fs.existsSync(logFile) 
    ? JSON.parse(fs.readFileSync(logFile, 'utf8')) 
    : [];

  logData.push(logEntry);
  fs.writeFileSync(logFile, JSON.stringify(logData, null, 2));

  console.log('📝 Emergency access logged');
}

// Main execution
if (require.main === module) {
  console.log('🔓 Secure Credential Decryption Utility\n');

  if (process.argv.length < 4) {
    console.log('Usage: node decrypt-backup.js <backup-file> <passphrase>');
    console.log('');
    console.log('Example:');
    console.log('  node decrypt-backup.js credentials-backup-2024-01-01T12-00-00Z.encrypted my-secret-passphrase');
    process.exit(1);
  }

  const backupFile = process.argv[2];
  const passphrase = process.argv[3];

  if (!fs.existsSync(backupFile)) {
    console.error(`❌ Backup file not found: ${backupFile}`);
    process.exit(1);
  }

  try {
    console.log('🚨 EMERGENCY ACCESS - DISASTER RECOVERY MODE\n');

    decryptBackup(backupFile, passphrase);
    logEmergencyAccess();

    console.log('\n✅ Emergency access completed');
    console.log('⚠️  Remember to rotate all credentials after recovery!');

  } catch (error) {
    console.error('❌ Decryption failed:', error.message);

    // Log failed attempt
    const logFile = 'emergency-access.log';
    const logEntry = {
      timestamp: new Date().toISOString(),
      user: process.env.USER || 'unknown',
      host: require('os').hostname(),
      action: 'failed_decryption_attempt',
      error: error.message
    };

    if (fs.existsSync(logFile)) {
      const logData = JSON.parse(fs.readFileSync(logFile, 'utf8'));
      logData.push(logEntry);
      fs.writeFileSync(logFile, JSON.stringify(logData, null, 2));
    } else {
      fs.writeFileSync(logFile, JSON.stringify([logEntry], null, 2));
    }

    process.exit(1);
  }
}

